using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;

public static class BuildSettingsUpdater
{
    public static string Run()
    {
        var scenes = EditorBuildSettings.scenes.ToList();
        const string createRoomPath = "Assets/Scenes/CreateRoom.unity";

        if (!scenes.Any(scene => scene.path == createRoomPath))
        {
            scenes.Insert(0, new EditorBuildSettingsScene(createRoomPath, true));
            EditorBuildSettings.scenes = scenes.ToArray();
        }

        return "Build settings updated";
    }
}
